extension.description:
Расширение позволяет передавать коды партионного учета в сообщениях INVOIC и COINVOIC. Предназначено для систем, в которых данные по партиям хранятся в таблицах документов 1С.

Расширение не работает с подсистемами Контур.Маркировка или ИС МП(информационная система мониторинга продукции) от 1С.
Для такого варианта работы есть отдельное расширение. (Название "Коды маркировки - заполнение из типовых подсистем").

Расширение поддерживает работу с партионным учетом:
- Штучного товара;
- Весового товара;
- Есть возможность передачи множественных партий;
- Поддержана возможность формирования номера партии по рекомендации от "Честного знака".

event.Code:
// Описание:
// 	Позволяет произвольно обработать подготовленное сообщение непосредственно перед отправкой (можно использовать, например, для отмены отправки сообщения)..
// 
// Параметры:
// 	Сообщение - Структура - Сообщение EDI в представлении 1С.
// 	ДокументСсылка - Нет данных - Описание параметра находится в разработке.
// 	Параметры - Нет данных - Описание параметра находится в разработке.
// 
// Возвращаемое значение:
// 	Структура
// 	Структура результатов, внутри которой ожидается структура «Сообщение».

Сообщение = Параметры.Сообщение;
ДокументСсылка = Параметры.ДокументСсылка;

Если Сообщение.ТипСообщения = "INVOIC" ИЛИ Сообщение.ТипСообщения = "COINVOIC" Тогда

	ИспользоватьСобственнуюЛогикуЗаполнения = Ложь;

	Если ИспользоватьСобственнуюЛогикуЗаполнения Тогда 

		//Необходим идентификатор строки товаров для сопоставления таблиц, но существующие использовать нельзя, 
		//т.к. есть расширения меняющие идентификаторы строк при распределении товаров по паллетам.
		НомерСтроки = 1;
		Для каждого СтрокаТоваров Из Сообщение.Товары Цикл
			СтрокаТоваров.НомерСтрокиПартионныйУчет = НомерСтроки;
			НомерСтроки = НомерСтроки + 1;
		КонецЦикла;

		//Коды партионного учета хранятся в отдельной таблице значений сообщения. 
		//Таблица описана через особенности сообщения (полный список колонок в ДобавитьОсобенностиСообщения)
		//
		//НомераПартий - ТаблицаЗначений
		//	НомерСтрокиПартионныйУчет - Строка - Не обязательно к заполнению. Идентификатор для сопоставления таблицы партий и таблицы товаров. 
		//										 Не заполняется в табилце партий в типовой логике, но может быть использован в доработках,
		//										 для того чтобы явно указать к какой строке относится текущий код партионного учета. Если не указывать, то расширение распределит указанные партии самостоятельно по товарам сообщения в момент формирования XML.
		//	Номенклатура - СправочникСсылка - Обязательно к заполнению.
		//	ХарактеристикаНоменклатуры - СправочникСсылка - Не обязательно к заполнению. Указание харакетристик в таблице партий улучшит распределение партий по товарам сообщения при наличии характеристик в товарах сообщения.
		//	НомерПартии - Строка - Обязательно к заполнению. Номер партии зарегистрированный в Честном знаке (этот номер без изменений будет передан в УПД).
		//	GTINКодаМаркировки - Строка - Обязательно к заполнению. GTIN товара в Честном знаке.
		//	Количество - Число - Обязательно к заполнению. Количество товара партии в штуках. Будет без пересчетов передаваться в УПД.
		//	КоличествоДоКорректировки - Число - Обязательно для COINVOIC. Количество товара партии в штуках до корректировки.
		//	ЭтоВесовойТовар - Булево - Необходимо установить Истину для весового товара.
		//	Вес - Число - Обязательно для весового товара. Вес товаров партии в граммах.
		//	ВесДоКорректировки - Число - Обязательно для весового товара в COINVOIC. Вес всей партии в граммах до корректировки.
		//
		//В доработках необходимо:
		//	1. Заполнить таблицу НомераПартий.
		//	2. Для товара подлежащего партионному учету необходимо в таблице товаров установить поле ЭтоПартионныйУчет в значение Истина
		//
		//Например:
		//		
		//		Для каждого СтрокаТоваров Из Сообщение.Товары Цикл
		//			
		//			СтрокаТоваров.ЭтоПартионныйУчет = Истина;
		//			
		//			ИнформацияОПартии = Сообщение.НомераПартий.Добавить();
		//			ИнформацияОПартии.НомерСтрокиПартионныйУчет = СтрокаТоваров.НомерСтрокиПартионныйУчет;
		//			ИнформацияОПартии.Номенклатура = СтрокаТоваров.Номенклатура;
		//			ИнформацияОПартии.Количество = СтрокаТоваров.Количество;
		//			ИнформацияОПартии.НомерПартии = Строка(СтрокаТоваров.Серия);
		//			ИнформацияОПартии.ЭтоВесовойТовар = Истина;
		//			ИнформацияОПартии.Вес = СтрокаТоваров.Количество * 1000;
		//			
		//			Если Сообщение.ТипСообщения = "COINVOIC" Тогда
		//				ИнформацияОПартии.КоличествоДоКорректировки = СтрокаТоваров.КоличествоДо;
		//				ИнформацияОПартии.ВесДоКорректировки = СтрокаТоваров.КоличествоДо * 1000;
		//			КонецЕсли;
		//			
		//		КонецЦикла;

	Иначе 

		Сообщение.НомераПартий.Очистить();
		ЕстьТоварыПартионногоУчета = Ложь;

		ИнтерфейсРасширения = ОбработкаСобытияПодключаемогоМодуля("ИнтерфейсРасширения_BatchMarking_UPD970");
		НастройкиРасширения = ИнтерфейсРасширения.ЗагрузитьНастройкиРасширения();

		Если ТипЗнч(НастройкиРасширения.ИспользоватьПередачуКодовУКД) = Тип("Булево") Тогда
			ИспользоватьПередачуКодовУКД = НастройкиРасширения.ИспользоватьПередачуКодовУКД;
		Иначе
			ИспользоватьПередачуКодовУКД = Истина;
		КонецЕсли;

		Если Сообщение.ТипСообщения = "INVOIC" ИЛИ ИспользоватьПередачуКодовУКД Тогда 

			Если Не НастройкиРасширения.НастройкиКомпоновкиМолочнаяПродукция = Неопределено Тогда 

				НастройкиКомпоновки = НастройкиРасширения.НастройкиКомпоновкиМолочнаяПродукция;
				НоменклатураСообщения = ОбработкаСобытияПодключаемогоМодуля("ПолучитьНоменклатуруСообщения_BatchMarking_UPD970",,Новый Структура("Сообщение", Сообщение));
				ДетальныеНастройкиНоменклатуры = ИнтерфейсРасширения.ДетальныеНастройкиНоменклатурыПартионногоУчета(НастройкиКомпоновки, НоменклатураСообщения, Истина);	
				ЕстьТоварыПартионногоУчета = ДетальныеНастройкиНоменклатуры.Количество() > 0;
				СворачиваниеВозможно = Не Сообщение.Товары.Колонки.Найти("СписокНоменклатуры") = Неопределено;

				ОтборСтрок = Новый Структура;

				Для каждого СтрокаТовара Из Сообщение.Товары Цикл

					СтрокиДетальныхНастроек = Новый Массив;

					Если ЗначениеЗаполнено(СтрокаТовара.Номенклатура) Тогда 

						ОтборСтрок.Вставить("НоменклатураСсылка", СтрокаТовара.Номенклатура);
						ОтборСтрок.Вставить("ХарактеристикаНоменклатуры", Строка(СтрокаТовара.ХарактеристикаНоменклатуры));
						ОтборСтрок.Вставить("ЕдиницаИзмерения", Строка(СтрокаТовара.ЕдиницаИзмерения));

						ВариантыПоиска = Новый Массив;
						ВариантыПоиска.Добавить("НоменклатураСсылка,ХарактеристикаНоменклатуры,ЕдиницаИзмерения");
						ВариантыПоиска.Добавить("НоменклатураСсылка,ХарактеристикаНоменклатуры");
						ВариантыПоиска.Добавить("НоменклатураСсылка,ЕдиницаИзмерения");
						ВариантыПоиска.Добавить("НоменклатураСсылка");

						СтрокиДетальныхНастроек = НайтиСтрокиВТаблицеПоВариантамПоиска(ДетальныеНастройкиНоменклатуры, 
																					ОтборСтрок, 
																					ВариантыПоиска);

					ИначеЕсли СворачиваниеВозможно И ЗначениеЗаполнено(СтрокаТовара.СписокНоменклатуры) Тогда 

						Для каждого СвернутаяНоменклатура Из СтрокаТовара.СписокНоменклатуры Цикл
							Номенклатура = СвернутаяНоменклатура.Значение;
							ОтборСтрок.Вставить("НоменклатураСсылка", Номенклатура);
							СтрокиДетальныхНастроек = ДетальныеНастройкиНоменклатуры.НайтиСтроки(ОтборСтрок);
							Если СтрокиДетальныхНастроек.Количество() > 0 Тогда
								Прервать;
							КонецЕсли;
						КонецЦикла;

					КонецЕсли;

					Если СтрокиДетальныхНастроек.Количество() > 0 Тогда

						СтрокаТовара.ЭтоПартионныйУчет = Истина;
						СтрокаТовара.ЭтоВесовойТовар = СтрокиДетальныхНастроек[0].ЭтоВесовойТовар;
						СтрокаТовара.GTINПартионногоУчета = СтрокиДетальныхНастроек[0].GTINНацКаталога;
						СтрокаТовара.Числитель_ПартионныйУчет = СтрокиДетальныхНастроек[0].Числитель;
						СтрокаТовара.Знаменатель_ПартионныйУчет = СтрокиДетальныхНастроек[0].Знаменатель;
						СтрокаТовара.ЧислительВес_ПартионныйУчет = СтрокиДетальныхНастроек[0].ЧислительВес;
						СтрокаТовара.ЗнаменательВес_ПартионныйУчет = СтрокиДетальныхНастроек[0].ЗнаменательВес;

					КонецЕсли;
				КонецЦикла;

			КонецЕсли;

			Если ЕстьТоварыПартионногоУчета Тогда

				Если Сообщение.Исправление = Истина Тогда
					ТипДокументаСчетФактура = ПолучитьТипЗначенияОбъекта("ТипДокументаСчетФактура");
					Если ЗначениеЗаполнено(ТипДокументаСчетФактура) И ТипЗнч(Сообщение.Документ1С) = Тип(ТипДокументаСчетФактура) Тогда 
						ДокументСодержащийПартии = ПолучитьКорректировкуРеализацииСчетаФактуры(Сообщение.Документ1С);
						Если ДокументСодержащийПартии = Неопределено Тогда
							ДокументСодержащийПартии = Сообщение.Накладная1С;
						КонецЕсли;
					Иначе
						ДокументСодержащийПартии = Сообщение.Документ1С;
					КонецЕсли;
//++НЕВ
				ИначеЕсли ТипЗнч(Сообщение.Документ1С) = Тип("ДокументСсылка.СчетФактураВыданный") 
						и ТипЗнч(Сообщение.Документ1С.ДокументОснование) = Тип("ДокументСсылка.КорректировкаРеализации") Тогда
						ДокументСодержащийПартии = Сообщение.Документ1С.ДокументОснование;
//--НЕВ
				Иначе
					ДокументСодержащийПартии = Сообщение.Накладная1С;
				КонецЕсли;

				ИмяДокумента = Неопределено;

				Если Не ДокументСодержащийПартии = Неопределено 
					И ДокументСодержащийПартии.Метаданные().Имя = НастройкиРасширения.ТипДокументаНакладная Тогда

					ИмяДокумента = НастройкиРасширения.ТипДокументаНакладная;
					ИмяТаблицы = НастройкиРасширения.ТаблицаНакладной;

					ПутьРеквизитаНоменклатура = НастройкиРасширения.ПутьРеквизитаНоменклатура;
					ПутьРеквизитаХарактеристика = НастройкиРасширения.ПутьРеквизитаХарактеристика;
					ПутьРеквизитаНомерПартии = НастройкиРасширения.ПутьРеквизитаНакладная;
					ПутьРеквизитаДатаПроизводства = НастройкиРасширения.ПутьРеквизитаДатаПроизводства;
					ПутьРеквизитаКоличество = НастройкиРасширения.ПутьРеквизитаКоличество;
					ПутьРеквизитаЕдиницаИзмерения = НастройкиРасширения.ПутьРеквизитаЕдиницаИзмерения;

				ИначеЕсли Не ДокументСодержащийПартии = Неопределено 
					И ДокументСодержащийПартии.Метаданные().Имя = НастройкиРасширения.ТипДокументаКорректировка Тогда

					ИмяДокумента = НастройкиРасширения.ТипДокументаКорректировка;
					ИмяТаблицы =  НастройкиРасширения.ТаблицаКорректировки;

					ПутьРеквизитаНоменклатура = НастройкиРасширения.ПутьРеквизитаНоменклатураКорректировка;
					ПутьРеквизитаХарактеристика = НастройкиРасширения.ПутьРеквизитаХарактеристикаКорректировка;
					ПутьРеквизитаНомерПартии = НастройкиРасширения.ПутьРеквизитаКорректировкиПосле;
					ПутьРеквизитаДатаПроизводства = НастройкиРасширения.ПутьРеквизитаДатаПроизводстваКорректировка;
					ПутьРеквизитаКоличество = НастройкиРасширения.ПутьРеквизитаКоличествоКорректировка;
					ПутьРеквизитаЕдиницаИзмерения = НастройкиРасширения.ПутьРеквизитаЕдиницаИзмеренияКорректировка;

				КонецЕсли;

				Если ЗначениеЗаполнено(ИмяДокумента) Тогда

					Запрос = Новый Запрос;
					Запрос.Текст = "ВЫБРАТЬ
					|	ТаблицаДокумента.&ПутьРеквизитаНоменклатура КАК Номенклатура,
					|	ТаблицаДокумента.&ПутьРеквизитаХарактеристика КАК ХарактеристикаНоменклатуры,
					|	ТаблицаДокумента.&ПутьРеквизитаЕдиницаИзмерения КАК ЕдиницаИзмерения,
					|	ТаблицаДокумента.&ПутьРеквизитаНомерПартии КАК НомерПартии,
					|	ТаблицаДокумента.&ПутьРеквизитаДатаПроизводства КАК ДатаПартии,
					|	ТаблицаДокумента.&ПутьРеквизитаКоличество КАК Количество
					|ИЗ
					|	Документ.&ИмяДокумента.&ИмяТаблицыДокумента КАК ТаблицаДокумента
					|ГДЕ
					|	ТаблицаДокумента.Ссылка = &Ссылка
					|	И ТаблицаДокумента.&ПутьРеквизитаНоменклатура В (&МассивНоменклатуры)";

					Запрос.Текст = СтрЗаменить(Запрос.Текст, "&ИмяДокумента", ИмяДокумента);
					Запрос.Текст = СтрЗаменить(Запрос.Текст, "&ИмяТаблицыДокумента", ИмяТаблицы);
					Запрос.Текст = СтрЗаменить(Запрос.Текст, "&ПутьРеквизитаНоменклатура", ПутьРеквизитаНоменклатура);
					Запрос.Текст = СтрЗаменить(Запрос.Текст, "&ПутьРеквизитаНомерПартии", ПутьРеквизитаНомерПартии);
					Запрос.Текст = СтрЗаменить(Запрос.Текст, "&ПутьРеквизитаКоличество", ПутьРеквизитаКоличество);

					Если ЗначениеЗаполнено(ПутьРеквизитаХарактеристика) Тогда
						Запрос.Текст = СтрЗаменить(Запрос.Текст, "&ПутьРеквизитаХарактеристика", ПутьРеквизитаХарактеристика);
					Иначе
						Запрос.Текст = СтрЗаменить(Запрос.Текст, "ТаблицаДокумента.&ПутьРеквизитаХарактеристика", "НЕОПРЕДЕЛЕНО");
					КонецЕсли;

					Если ЗначениеЗаполнено(ПутьРеквизитаЕдиницаИзмерения) Тогда
						Запрос.Текст = СтрЗаменить(Запрос.Текст, "&ПутьРеквизитаЕдиницаИзмерения", ПутьРеквизитаЕдиницаИзмерения);
					Иначе
						Запрос.Текст = СтрЗаменить(Запрос.Текст, "ТаблицаДокумента.&ПутьРеквизитаЕдиницаИзмерения", "НЕОПРЕДЕЛЕНО");
					КонецЕсли;

					Если НастройкиРасширения.ВариантНастройки = "СобиратьИзОтдельныхЧастей" Тогда
						Запрос.Текст = СтрЗаменить(Запрос.Текст, "&ПутьРеквизитаДатаПроизводства", ПутьРеквизитаДатаПроизводства);
					Иначе
						Запрос.Текст = СтрЗаменить(Запрос.Текст, "ТаблицаДокумента.&ПутьРеквизитаДатаПроизводства", "НЕОПРЕДЕЛЕНО");
					КонецЕсли;

					Запрос.УстановитьПараметр("Ссылка", ДокументСодержащийПартии);	
					Запрос.УстановитьПараметр("МассивНоменклатуры", ДетальныеНастройкиНоменклатуры.ВыгрузитьКолонку("НоменклатураСсылка"));
					//++НЕВ
					Если ИмяДокумента = "РеализацияТоваровУслуг" Тогда
							Запрос.Текст = "ВЫБРАТЬ
							               |	ТаблицаДокумента.Номенклатура КАК Номенклатура,
							               |	ТаблицаДокумента.Характеристика КАК ХарактеристикаНоменклатуры,
							               |	ТаблицаДокумента.Упаковка КАК ЕдиницаИзмерения,
							               |	ТаблицаДокумента.Серия.Номер КАК НомерПартии,
							               |	НЕОПРЕДЕЛЕНО КАК ДатаПартии,
							               |	ТаблицаДокумента.Количество КАК Количество,
							               |	ТаблицаДокумента.СтрокаОрдера КАК СтрокаОрдера,
							               |	ТаблицаДокумента.ЗаказКлиента КАК ЗаказКлиента,
							               |	ТаблицаДокумента.КоличествоКодовОСУ КАК КоличествоКодовОСУ
							               |ПОМЕСТИТЬ ВТ
							               |ИЗ
							               |	Документ.РеализацияТоваровУслуг.Товары КАК ТаблицаДокумента
							               |ГДЕ
							               |	ТаблицаДокумента.Ссылка = &Ссылка
							               |	И ТаблицаДокумента.Номенклатура В(&МассивНоменклатуры)
							               |;
							               |
							               |////////////////////////////////////////////////////////////////////////////////
							               |ВЫБРАТЬ
							               |	МИНИМУМ(РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Ссылка) КАК РасходныйОрдер,
							               |	РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Номенклатура КАК Номенклатура,
							               |	РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Характеристика КАК Характеристика,
							               |	РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Распоряжение КАК Распоряжение
							               |ПОМЕСТИТЬ ПодходящиеОрдера
							               |ИЗ
							               |	Документ.РасходныйОрдерНаТовары.ТоварыПоРаспоряжениям КАК РасходныйОрдерНаТоварыТоварыПоРаспоряжениям
							               |ГДЕ
							               |	РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Ссылка.Проведен = ИСТИНА
							               |	И (РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Распоряжение, РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Номенклатура, РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Характеристика) В
							               |			(ВЫБРАТЬ
							               |				ВТ.ЗаказКлиента КАК ЗаказКлиента,
							               |				ВТ.Номенклатура КАК Номенклатура,
							               |				ВТ.ХарактеристикаНоменклатуры КАК ХарактеристикаНоменклатуры
							               |			ИЗ
							               |				ВТ КАК ВТ)
							               |
							               |СГРУППИРОВАТЬ ПО
							               |	РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Распоряжение,
							               |	РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Номенклатура,
							               |	РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Характеристика
							               |;
							               |
							               |////////////////////////////////////////////////////////////////////////////////
							               |ВЫБРАТЬ
							               |	ВТ.Номенклатура КАК Номенклатура,
							               |	ВТ.ХарактеристикаНоменклатуры КАК ХарактеристикаНоменклатуры,
							               |	ВТ.ЕдиницаИзмерения КАК ЕдиницаИзмерения,
							               |	ВТ.НомерПартии КАК _НомерПартии,
							               |	РасходныйОрдерНаТоварыОтгружаемыеТовары.Серия.ДатаПроизводства КАК ДатаПартии,
							               |	ВТ.Количество КАК Количество,
							               |	ВТ.СтрокаОрдера КАК СтрокаОрдера,
							               |	ВТ.ЗаказКлиента КАК ЗаказКлиента,
							               |	ПодходящиеОрдера.РасходныйОрдер КАК РасходныйОрдер,
							               |	РасходныйОрдерНаТоварыОтгружаемыеТовары.Серия.Номер КАК НомерПартии,
							               |	РасходныйОрдерНаТоварыОтгружаемыеТовары.Серия.ДатаПроизводства КАК ДатаПроизводства,
							               |	ВТ.КоличествоКодовОСУ КАК КоличествоКодовОСУ,
							               |	0 КАК КоличествоДо,
							               |	0 КАК КоличествоКодовОСУДо,
							               |	1 КАК КоличествоСтрокВРеализации
							               |ИЗ
							               |	ВТ КАК ВТ
							               |		ЛЕВОЕ СОЕДИНЕНИЕ ПодходящиеОрдера КАК ПодходящиеОрдера
							               |		ПО ВТ.Номенклатура = ПодходящиеОрдера.Номенклатура
							               |			И ВТ.ХарактеристикаНоменклатуры = ПодходящиеОрдера.Характеристика
							               |			И ВТ.ЗаказКлиента = ПодходящиеОрдера.Распоряжение
							               |		ЛЕВОЕ СОЕДИНЕНИЕ Документ.РасходныйОрдерНаТовары.ОтгружаемыеТовары КАК РасходныйОрдерНаТоварыОтгружаемыеТовары
							               |		ПО ВТ.Номенклатура = РасходныйОрдерНаТоварыОтгружаемыеТовары.Номенклатура
							               |			И ВТ.ХарактеристикаНоменклатуры = РасходныйОрдерНаТоварыОтгружаемыеТовары.Характеристика
							               |			И ВТ.СтрокаОрдера = РасходныйОрдерНаТоварыОтгружаемыеТовары.НомерСтроки
							               |			И (ПодходящиеОрдера.РасходныйОрдер = РасходныйОрдерНаТоварыОтгружаемыеТовары.Ссылка)";
						ИначеЕсли ИмяДокумента = "КорректировкаРеализации" Тогда
							Запрос.Текст = "ВЫБРАТЬ
							               |	Документ.Ссылка.МоментВремени КАК ДокументОснованиеМоментВремени
							               |ПОМЕСТИТЬ ЗначениеУсловияПоМоментуВремени
							               |ИЗ
							               |	Документ.КорректировкаРеализации КАК Документ
							               |ГДЕ
							               |	Документ.Ссылка = &Ссылка
							               |;
							               |
							               |////////////////////////////////////////////////////////////////////////////////
							               |ВЫБРАТЬ
							               |	КорректировкаРеализации.Ссылка КАК Ссылка,
							               |	КорректировкаРеализации.ДокументОснование КАК ДокументОснование,
							               |	КорректировкаРеализации.МоментВремени КАК МоментВремени
							               |ПОМЕСТИТЬ ВсеВозможныеКорректировки
							               |ИЗ
							               |	Документ.КорректировкаРеализации КАК КорректировкаРеализации
							               |		ВНУТРЕННЕЕ СОЕДИНЕНИЕ ЗначениеУсловияПоМоментуВремени КАК ЗначениеУсловияПоМоментуВремени
							               |		ПО КорректировкаРеализации.МоментВремени <= ЗначениеУсловияПоМоментуВремени.ДокументОснованиеМоментВремени
							               |ГДЕ
							               |	КорректировкаРеализации.ДокументОснование В
							               |			(ВЫБРАТЬ
							               |				КорректировкаРеализации.ДокументОснование КАК ДокументОснованиеДокументОснование
							               |			ИЗ
							               |				Документ.КорректировкаРеализации КАК КорректировкаРеализации
							               |			ГДЕ
							               |				КорректировкаРеализации.Ссылка = &Ссылка)
							               |	И КорректировкаРеализации.Проведен = ИСТИНА
							               |;
							               |
							               |////////////////////////////////////////////////////////////////////////////////
							               |ВЫБРАТЬ
							               |	МИНИМУМ(ВложенныйЗапрос.НомерСтроки) КАК НомерСтроки,
							               |	ВложенныйЗапрос.Номенклатура КАК Номенклатура,
							               |	ВложенныйЗапрос.Характеристика КАК Характеристика,
							               |	СУММА(ВложенныйЗапрос.КоличествоУпаковок) КАК КоличествоУпаковокДо,
							               |	СУММА(ВложенныйЗапрос.Количество) КАК КоличествоДо,
							               |	МИНИМУМ(ВложенныйЗапрос.СтрокаОрдера) КАК СтрокаОрдера,
							               |	СУММА(ВложенныйЗапрос.КоличествоКодовОСУ) КАК КоличествоКодовОСУДо,
							               |	0 КАК КоличествоПосле,
							               |	0 КАК КоличествоКодовОСУПосле,
							               |	0 КАК КоличествоУпаковокПосле,
							               |	ВложенныйЗапрос.КоличествоСтрокВРеализации КАК КоличествоСтрокВРеализации,
							               |	ВложенныйЗапрос.ЕдиницаИзмерения КАК ЕдиницаИзмерения
							               |ПОМЕСТИТЬ ДанныеДоИПослеКорректировки
							               |ИЗ
							               |	(ВЫБРАТЬ
							               |		МИНИМУМ(РеализацияТоваровУслугТовары.НомерСтроки) КАК НомерСтроки,
							               |		РеализацияТоваровУслугТовары.Номенклатура КАК Номенклатура,
							               |		РеализацияТоваровУслугТовары.Характеристика КАК Характеристика,
							               |		СУММА(РеализацияТоваровУслугТовары.КоличествоУпаковок) КАК КоличествоУпаковок,
							               |		СУММА(РеализацияТоваровУслугТовары.Количество) КАК Количество,
							               |		МИНИМУМ(РеализацияТоваровУслугТовары.СтрокаОрдера) КАК СтрокаОрдера,
							               |		СУММА(РеализацияТоваровУслугТовары.КоличествоКодовОСУ) КАК КоличествоКодовОСУ,
							               |		КОЛИЧЕСТВО(РАЗЛИЧНЫЕ РеализацияТоваровУслугТовары.НомерСтроки) КАК КоличествоСтрокВРеализации,
							               |		РеализацияТоваровУслугТовары.Упаковка КАК ЕдиницаИзмерения
							               |	ИЗ
							               |		Документ.РеализацияТоваровУслуг.Товары КАК РеализацияТоваровУслугТовары
							               |	ГДЕ
							               |		РеализацияТоваровУслугТовары.Ссылка В
							               |				(ВЫБРАТЬ
							               |					ВсеВозможныеКорректировки.ДокументОснование КАК ДокументОснование
							               |				ИЗ
							               |					ВсеВозможныеКорректировки КАК ВсеВозможныеКорректировки)
							               |	
							               |	СГРУППИРОВАТЬ ПО
							               |		РеализацияТоваровУслугТовары.Номенклатура,
							               |		РеализацияТоваровУслугТовары.Характеристика,
							               |		РеализацияТоваровУслугТовары.Упаковка
							               |	
							               |	ОБЪЕДИНИТЬ ВСЕ
							               |	
							               |	ВЫБРАТЬ
							               |		NULL,
							               |		КорректировкаРеализацииРасхождения.Номенклатура,
							               |		КорректировкаРеализацииРасхождения.Характеристика,
							               |		КорректировкаРеализацииРасхождения.КоличествоУпаковок,
							               |		КорректировкаРеализацииРасхождения.Количество,
							               |		0,
							               |		КорректировкаРеализацииРасхождения.КоличествоКодовОСУ,
							               |		0,
							               |		КорректировкаРеализацииРасхождения.Упаковка
							               |	ИЗ
							               |		Документ.КорректировкаРеализации.Расхождения КАК КорректировкаРеализацииРасхождения
							               |			ВНУТРЕННЕЕ СОЕДИНЕНИЕ ВсеВозможныеКорректировки КАК ВсеВозможныеКорректировки
							               |			ПО КорректировкаРеализацииРасхождения.Ссылка = ВсеВозможныеКорректировки.Ссылка
							               |			ВНУТРЕННЕЕ СОЕДИНЕНИЕ ЗначениеУсловияПоМоментуВремени КАК ЗначениеУсловияПоМоментуВремени
							               |			ПО КорректировкаРеализацииРасхождения.Ссылка.МоментВремени < ЗначениеУсловияПоМоментуВремени.ДокументОснованиеМоментВремени) КАК ВложенныйЗапрос
							               |
							               |СГРУППИРОВАТЬ ПО
							               |	ВложенныйЗапрос.Номенклатура,
							               |	ВложенныйЗапрос.Характеристика,
							               |	ВложенныйЗапрос.КоличествоСтрокВРеализации,
							               |	ВложенныйЗапрос.ЕдиницаИзмерения
							               |
							               |ОБЪЕДИНИТЬ ВСЕ
							               |
							               |ВЫБРАТЬ
							               |	NULL,
							               |	КорректировкаРеализацииРасхождения.Номенклатура,
							               |	КорректировкаРеализацииРасхождения.Характеристика,
							               |	0,
							               |	0,
							               |	0,
							               |	0,
							               |	КорректировкаРеализацииРасхождения.Количество,
							               |	КорректировкаРеализацииРасхождения.КоличествоКодовОСУ,
							               |	КорректировкаРеализацииРасхождения.КоличествоУпаковок,
							               |	0,
							               |	КорректировкаРеализацииРасхождения.Упаковка
							               |ИЗ
							               |	Документ.КорректировкаРеализации.Расхождения КАК КорректировкаРеализацииРасхождения
							               |		ВНУТРЕННЕЕ СОЕДИНЕНИЕ ЗначениеУсловияПоМоментуВремени КАК ЗначениеУсловияПоМоментуВремени
							               |		ПО КорректировкаРеализацииРасхождения.Ссылка.МоментВремени = ЗначениеУсловияПоМоментуВремени.ДокументОснованиеМоментВремени
							               |;
							               |
							               |////////////////////////////////////////////////////////////////////////////////
							               |ВЫБРАТЬ РАЗЛИЧНЫЕ
							               |	РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Ссылка КАК Ссылка,
							               |	РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Распоряжение КАК Распоряжение
							               |ПОМЕСТИТЬ ОтборРасходныхОрдеров
							               |ИЗ
							               |	Документ.РасходныйОрдерНаТовары.ТоварыПоРаспоряжениям КАК РасходныйОрдерНаТоварыТоварыПоРаспоряжениям
							               |ГДЕ
							               |	РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Распоряжение В
							               |			(ВЫБРАТЬ РАЗЛИЧНЫЕ
							               |				ВсеВозможныеКорректировки.ДокументОснование.ЗаказКлиента КАК ДокументОснованиеЗаказКлиента
							               |			ИЗ
							               |				ВсеВозможныеКорректировки КАК ВсеВозможныеКорректировки)
							               |	И РасходныйОрдерНаТоварыТоварыПоРаспоряжениям.Ссылка.Проведен = ИСТИНА
							               |;
							               |
							               |////////////////////////////////////////////////////////////////////////////////
							               |ВЫБРАТЬ
							               |	МИНИМУМ(РасходныйОрдерНаТоварыОтгружаемыеТовары.НомерСтроки) КАК НомерСтроки,
							               |	РасходныйОрдерНаТоварыОтгружаемыеТовары.Номенклатура КАК Номенклатура,
							               |	РасходныйОрдерНаТоварыОтгружаемыеТовары.Характеристика КАК Характеристика,
							               |	МИНИМУМ(РасходныйОрдерНаТоварыОтгружаемыеТовары.Серия) КАК Серия,
							               |	РасходныйОрдерНаТоварыОтгружаемыеТовары.Упаковка КАК Упаковка,
							               |	СУММА(РасходныйОрдерНаТоварыОтгружаемыеТовары.Количество) КАК Количество,
							               |	СУММА(РасходныйОрдерНаТоварыОтгружаемыеТовары.КоличествоУпаковок) КАК КоличествоУпаковок
							               |ПОМЕСТИТЬ ДанныеИзСвязанныхРасходныхОрдеров
							               |ИЗ
							               |	Документ.РасходныйОрдерНаТовары.ОтгружаемыеТовары КАК РасходныйОрдерНаТоварыОтгружаемыеТовары
							               |		ВНУТРЕННЕЕ СОЕДИНЕНИЕ ОтборРасходныхОрдеров КАК ОтборРасходныхОрдеров
							               |		ПО РасходныйОрдерНаТоварыОтгружаемыеТовары.Ссылка = ОтборРасходныхОрдеров.Ссылка
							               |
							               |СГРУППИРОВАТЬ ПО
							               |	РасходныйОрдерНаТоварыОтгружаемыеТовары.Номенклатура,
							               |	РасходныйОрдерНаТоварыОтгружаемыеТовары.Характеристика,
							               |	РасходныйОрдерНаТоварыОтгружаемыеТовары.Упаковка
							               |;
							               |
							               |////////////////////////////////////////////////////////////////////////////////
							               |ВЫБРАТЬ
							               |	МАКСИМУМ(ДанныеДоИПослеКорректировки.НомерСтроки) КАК НомерСтроки,
							               |	ДанныеДоИПослеКорректировки.Номенклатура КАК Номенклатура,
							               |	ДанныеДоИПослеКорректировки.Характеристика КАК Характеристика,
							               |	СУММА(ДанныеДоИПослеКорректировки.КоличествоУпаковокДо) КАК КоличествоУпаковокДо,
							               |	СУММА(ДанныеДоИПослеКорректировки.КоличествоДо) КАК КоличествоДо,
							               |	МАКСИМУМ(ДанныеДоИПослеКорректировки.СтрокаОрдера) КАК СтрокаОрдера,
							               |	СУММА(ДанныеДоИПослеКорректировки.КоличествоКодовОСУДо) КАК КоличествоКодовОСУДо,
							               |	СУММА(ДанныеДоИПослеКорректировки.КоличествоПосле) КАК КоличествоПосле,
							               |	СУММА(ДанныеДоИПослеКорректировки.КоличествоКодовОСУПосле) КАК КоличествоКодовОСУПосле,
							               |	СУММА(ДанныеДоИПослеКорректировки.КоличествоУпаковокПосле) КАК КоличествоУпаковокПосле,
							               |	СУММА(ДанныеДоИПослеКорректировки.КоличествоСтрокВРеализации) КАК КоличествоСтрокВРеализации,
							               |	ДанныеДоИПослеКорректировки.ЕдиницаИзмерения КАК ЕдиницаИзмерения
							               |ПОМЕСТИТЬ ДанныеДоИПослеКорректировкиСгруппированные
							               |ИЗ
							               |	ДанныеДоИПослеКорректировки КАК ДанныеДоИПослеКорректировки
							               |
