НоваяОсобенность.ТипЗначения1С = "Число" ;
НоваяОсобенность.ИмяТаблицы = "НомераПартий";

//--НЕВ

// Описание:
// 	Признак того, что сообщение COINVOIC формируется в формате УКД 5.03 (УКД29).
// 	Управляется функциональной опцией UCD29.
// 
// Возвращаемое значение:
// 	Булево
// 	Признак формирования COINVOIC в формате УКД29.

Попытка
	УКД29 = Вычислить("ПолучитьФункциональнуюОпциюEDI(""UCD29"", Ложь)");
Исключение
	УКД29 = Ложь;
КонецПопытки;

Возврат УКД29;


lineItem = Параметры.lineItem;
Сообщение = Параметры.Сообщение;
СтрокаТоваров = Параметры.СтрокаТоваров;

Если Сообщение.ТипСообщения = "INVOIC" И СтрокаТоваров.ЭтоПартионныйУчет Тогда

	lineItem.controlIdentificationMarks.Очистить();

	СтрокаТоваров.КодыМаркировки.Очистить();
	Если СтрокаТоваров.Владелец().Колонки.Найти("GTINНацКаталога") <> Неопределено Тогда
		СтрокаТоваров.GTINНацКаталога = "";
	КонецЕсли;

	//Расчет количества товара, необходимого для поиска в информации о партиях
	КоличествоТовараВЕдиницах1С = СтрокаТоваров.Количество / КоэффициентEDIВ1С_Расчетный_КонтурEDI("В1С", СтрокаТоваров.КоэффициентEDIВ1С);
	Числитель = ?(ЗначениеЗаполнено(СтрокаТоваров.Числитель_ПартионныйУчет), СтрокаТоваров.Числитель_ПартионныйУчет, 1);
	Знаменатель = ?(ЗначениеЗаполнено(СтрокаТоваров.Знаменатель_ПартионныйУчет), СтрокаТоваров.Знаменатель_ПартионныйУчет, 1);
	НеобходимоеКоличествоТовара = КоличествоТовараВЕдиницах1С * Числитель / Знаменатель;
	//Сообщить(СтрШаблон("Количество:%1,КоличествоТовараВЕдиницах1С:%2, Числитель:%3, Знаменатель:%4 ",СтрокаТоваров.Количество,КоличествоТовараВЕдиницах1С,Числитель,Знаменатель));
	//Подбор подходящих партий
	ПодходящиеСтрокиПартий = Новый Массив;

	Если ЗначениеЗаполнено(СтрокаТоваров.НомерСтрокиПартионныйУчет) Тогда
		ПоискПоНомеруСтроки = Новый Структура("НомерСтрокиПартионныйУчет", СтрокаТоваров.НомерСтрокиПартионныйУчет);
		ПодходящиеСтрокиПартий = Сообщение.НомераПартий.НайтиСтроки(ПоискПоНомеруСтроки);
	КонецЕсли;

	Если Не ЗначениеЗаполнено(ПодходящиеСтрокиПартий) И ЗначениеЗаполнено(СтрокаТоваров.СписокНоменклатуры) Тогда

		Для каждого ЭлементСписка Из СтрокаТоваров.СписокНоменклатуры Цикл

			Отбор = Новый Структура;
			Отбор.Вставить("Номенклатура", ЭлементСписка.Значение);

			ПодходящиеПартииПоНоменклатуре = Сообщение.НомераПартий.НайтиСтроки(Отбор);
			Для каждого ПодходящаяСтрокаПартии Из ПодходящиеПартииПоНоменклатуре Цикл
				ПодходящиеСтрокиПартий.Добавить(ПодходящаяСтрокаПартии);	
			КонецЦикла;

		КонецЦикла;

	КонецЕсли;

	Если Не ЗначениеЗаполнено(ПодходящиеСтрокиПартий) Тогда

		СтруктураПоискаПартии = Новый Структура;
		СтруктураПоискаПартии.Вставить("Номенклатура", СтрокаТоваров.Номенклатура);
		СтруктураПоискаПартии.Вставить("ХарактеристикаНоменклатуры", СтрокаТоваров.ХарактеристикаНоменклатуры);
		СтруктураПоискаПартии.Вставить("Количество", НеобходимоеКоличествоТовара);

		ВариантыПоиска = Новый Массив;
		ВариантыПоиска.Добавить("Номенклатура,ХарактеристикаНоменклатуры,Количество");
		ВариантыПоиска.Добавить("Номенклатура,ХарактеристикаНоменклатуры");
		ВариантыПоиска.Добавить("Номенклатура,Количество");
		ВариантыПоиска.Добавить("Номенклатура");

		НайденныеСтрокиПартий = НайтиСтрокиВТаблицеПоВариантамПоиска(Сообщение.НомераПартий, СтруктураПоискаПартии, ВариантыПоиска);

		Для каждого СтрокаПартии Из НайденныеСтрокиПартий Цикл
			ПодходящиеСтрокиПартий.Добавить(СтрокаПартии);	
		КонецЦикла;

	КонецЕсли;

	//Определение конкретных партий для текущей строки товаров
	Если ЗначениеЗаполнено(ПодходящиеСтрокиПартий) Тогда

		Для каждого ПодходящаяПартия Из ПодходящиеСтрокиПартий Цикл

//++НЕВ
//Сообщить(""+ТипЗнч(ПодходящаяПартия.ЕдиницаИзмерения)+"  "+ПодходящаяПартия.ЕдиницаИзмерения);

Если ЗначениеЗаполнено( ПодходящаяПартия.ЕдиницаИзмерения ) Тогда 
	_Числитель = ПодходящаяПартия.ЕдиницаИзмерения.Числитель;
	_Знаменатель = ПодходящаяПартия.ЕдиницаИзмерения.Знаменатель;
	Иначе
	_Числитель = 1;
	_Знаменатель = 1;
КонецЕсли;

			Если СтрокаТоваров.ЭтоВесовойТовар = Истина и ПодходящаяПартия.Вес / 1000 <> НеобходимоеКоличествоТовара Тогда
				ВызватьИсключение(СтрШаблон("Невозможно подобрать партию (весовой товар необходимое количество:%1, подходящее количество %2)",НеобходимоеКоличествоТовара,ПодходящаяПартия.Вес/1000));
			ИначеЕсли Не СтрокаТоваров.ЭтоВесовойТовар = Истина и ПодходящаяПартия.Количество <> НеобходимоеКоличествоТовара * _Числитель / _Знаменатель Тогда
				ВызватьИсключение(СтрШаблон("Невозможно подобрать партию подходящее количество:%1, необходимое колиечество:%2",ПодходящаяПартия.Количество,НеобходимоеКоличествоТовара));
			КонецЕсли;

//--НЕВ			

			РаспределяемоеКоличество = Мин(ПодходящаяПартия.Количество, НеобходимоеКоличествоТовара * _Числитель / _Знаменатель);
			РаспределяемыйВес = ПодходящаяПартия.Вес;//++НЕВ * РаспределяемоеКоличество / ПодходящаяПартия.Количество; //--НЕВ


			ПодходящаяПартия.Количество = ПодходящаяПартия.Количество - РаспределяемоеКоличество;
			ПодходящаяПартия.Вес = ПодходящаяПартия.Вес - РаспределяемыйВес;
			НеобходимоеКоличествоТовара = НеобходимоеКоличествоТовара - РаспределяемоеКоличество * _Знаменатель / _Числитель;

			controlIdentificationMark = xmlСоздатьДочернийЭлементXDTO(lineItem, "controlIdentificationMarks");

//++НЕВ
			Если СтрокаТоваров.ЭтоВесовойТовар = Истина и ПодходящаяПартия.ДатаПартии < '20261101' Тогда
				controlIdentificationMark.type = "osu";
				Контент = "02" + ПодходящаяПартия.GTINКодаМаркировки + "37" + Формат(ПодходящаяПартия.КоличествоКодовОСУ, "ЧГ=");
			ИначеЕсли  ПодходящаяПартия.ДатаПартии < '20261101' Тогда
				controlIdentificationMark.type = "osu";
				Контент = "02" + ПодходящаяПартия.GTINКодаМаркировки + "37" + Формат(РаспределяемоеКоличество, "ЧГ=");
			ИначеЕсли СтрокаТоваров.ЭтоВесовойТовар = Истина Тогда
			//Если СтрокаТоваров.ЭтоВесовойТовар = Истина Тогда
				//--НЕВ				

				Контент = "02" 
				+ ПодходящаяПартия.GTINКодаМаркировки
				+ "37"
				+ Формат(
					//++НЕВ
					ПодходящаяПартия.КоличествоКодовОСУ //РаспределяемоеКоличество
					, "ЧДЦ=0; ЧГ=; ЧН=0")
				+ "3103"
				+ Формат(РаспределяемыйВес, "ЧЦ=9; ЧДЦ=0; ЧВН=; ЧГ=; ЧН=000000000");
				controlIdentificationMark.type = "MarkingWeightBatches";
			Иначе
				Контент = ПодходящаяПартия.GTINКодаМаркировки;
				controlIdentificationMark.quantity = Цел(РаспределяемоеКоличество);
				controlIdentificationMark.type = "MarkingBatches";
			КонецЕсли;

			Если Сообщение.Свойство("ВариантНастройкиПартионныйУчет") И Сообщение.ВариантНастройкиПартионныйУчет = "СобиратьИзОтдельныхЧастей" Тогда
				ДатаПроизводства = Формат(ПодходящаяПартия.ДатаПартии, "ДФ=yyMMdd");
				НомерПартии = ПодходящаяПартия.GTINКодаМаркировки + ДатаПроизводства + ПодходящаяПартия.НомерПартии;
			Иначе
				НомерПартии = ПодходящаяПартия.НомерПартии;
			КонецЕсли;
			//++НЕВ
			Если ПодходящаяПартия.ДатаПартии >= '20261101' Тогда
//--НЕВ							
			controlIdentificationMark.number = НомерПартии;
//++НЕВ
			КонецЕсли;
//--НЕВ			
			controlIdentificationMark.__content = Контент;

			Если ПодходящаяПартия.Количество = 0 Тогда
				Сообщение.НомераПартий.Удалить(ПодходящаяПартия);
			КонецЕсли;					

			Если НеобходимоеКоличествоТовара = 0 Тогда
				Прервать;
			КонецЕсли;

		КонецЦикла;

	КонецЕсли;

КонецЕсли;

Если Сообщение.ТипСообщения = "COINVOIC" И СтрокаТоваров.ЭтоПартионныйУчет Тогда

	СтрокаТоваров.КодыМаркировкиДо.Очистить();
	СтрокаТоваров.КодыМаркировкиПосле.Очистить();

	Если СтрокаТоваров.Владелец().Колонки.Найти("GTINНацКаталогаПосле") <> Неопределено Тогда
		СтрокаТоваров.GTINНацКаталогаДо = "";
		СтрокаТоваров.GTINНацКаталогаПосле = "";
	КонецЕсли;

	lineItem.controlIdentificationMarksAfter.Очистить();
	lineItem.controlIdentificationMarksBefore.Очистить();

	//Расчет количества товара, необходимого для поиска в информации о партиях

	Числитель = ?(ЗначениеЗаполнено(СтрокаТоваров.Числитель_ПартионныйУчет), СтрокаТоваров.Числитель_ПартионныйУчет, 1);
	Знаменатель = ?(ЗначениеЗаполнено(СтрокаТоваров.Знаменатель_ПартионныйУчет), СтрокаТоваров.Знаменатель_ПартионныйУчет, 1);


	КоличествоТовараВЕдиницах1СДоКорректировки = СтрокаТоваров.КоличествоДо / КоэффициентEDIВ1С_Расчетный_КонтурEDI("В1С", СтрокаТоваров.КоэффициентEDIВ1С);
	НеобходимоеКоличествоТовараДоКорректировки = КоличествоТовараВЕдиницах1СДоКорректировки * Числитель / Знаменатель;

	КоличествоТовараВЕдиницах1СПослеКорректировки = СтрокаТоваров.КоличествоПосле / КоэффициентEDIВ1С_Расчетный_КонтурEDI("В1С", СтрокаТоваров.КоэффициентEDIВ1С);
	НеобходимоеКоличествоТовараПослеКорректировки = КоличествоТовараВЕдиницах1СПослеКорректировки * Числитель / Знаменатель;

	//Подбор подходящих партий
	ПодходящиеСтрокиПартий = Новый Массив;

	Если ЗначениеЗаполнено(СтрокаТоваров.НомерСтрокиПартионныйУчет) Тогда
		ПоискПоНомеруСтроки = Новый Структура("НомерСтрокиПартионныйУчет", СтрокаТоваров.НомерСтрокиПартионныйУчет);
		ПодходящиеСтрокиПартий = Сообщение.НомераПартий.НайтиСтроки(ПоискПоНомеруСтроки);
	КонецЕсли;

	Если Не ЗначениеЗаполнено(ПодходящиеСтрокиПартий) И ЗначениеЗаполнено(СтрокаТоваров.СписокНоменклатуры) Тогда


		Для каждого ЭлементСписка Из СтрокаТоваров.СписокНоменклатуры Цикл

			Отбор = Новый Структура;
			Отбор.Вставить("Номенклатура", ЭлементСписка.Значение);

			ПодходящиеПартииПоНоменклатуре = Сообщение.НомераПартий.НайтиСтроки(Отбор);
			Для каждого ПодходящаяСтрокаПартии Из ПодходящиеПартииПоНоменклатуре Цикл
				ПодходящиеСтрокиПартий.Добавить(ПодходящаяСтрокаПартии);	
			КонецЦикла;

		КонецЦикла;

	КонецЕсли;

	Если Не ЗначениеЗаполнено(ПодходящиеСтрокиПартий) Тогда

		СтруктураПоискаПартии = Новый Структура;
		СтруктураПоискаПартии.Вставить("Номенклатура", СтрокаТоваров.Номенклатура);
		СтруктураПоискаПартии.Вставить("ХарактеристикаНоменклатуры", СтрокаТоваров.ХарактеристикаНоменклатуры);
		СтруктураПоискаПартии.Вставить("КоличествоДоКорректировки", НеобходимоеКоличествоТовараДоКорректировки);
		СтруктураПоискаПартии.Вставить("Количество", НеобходимоеКоличествоТовараПослеКорректировки);

		ВариантыПоиска = Новый Массив;
		ВариантыПоиска.Добавить("Номенклатура,ХарактеристикаНоменклатуры,КоличествоДоКорректировки,Количество");
		ВариантыПоиска.Добавить("Номенклатура,ХарактеристикаНоменклатуры");
		ВариантыПоиска.Добавить("Номенклатура");

		НайденныеСтрокиПартий = НайтиСтрокиВТаблицеПоВариантамПоиска(Сообщение.НомераПартий, СтруктураПоискаПартии, ВариантыПоиска);

		Для каждого СтрокаПартии Из НайденныеСтрокиПартий Цикл
			ПодходящиеСтрокиПартий.Добавить(СтрокаПартии);	
		КонецЦикла;

	КонецЕсли;

	//Определение конкретных партий для текущей строки товаров
	Если ЗначениеЗаполнено(ПодходящиеСтрокиПартий) Тогда

		Для каждого ПодходящаяПартия Из ПодходящиеСтрокиПартий Цикл

			РаспределяемоеКоличествоДо = Мин(ПодходящаяПартия.КоличествоДоКорректировки, НеобходимоеКоличествоТовараДоКорректировки);
			РаспределяемыйВесДо = 0;
			Если Не РаспределяемоеКоличествоДо = 0 Тогда
				РаспределяемыйВесДо = ПодходящаяПартия.ВесДоКорректировки * РаспределяемоеКоличествоДо / ПодходящаяПартия.КоличествоДоКорректировки;
			КонецЕсли;

			РаспределяемоеКоличествоПосле = Мин(ПодходящаяПартия.Количество, НеобходимоеКоличествоТовараПослеКорректировки);
			РаспределяемыйВесПосле = 0;
			Если Не РаспределяемоеКоличествоПосле = 0 Тогда
				РаспределяемыйВесПосле = ПодходящаяПартия.Вес * РаспределяемоеКоличествоПосле / ПодходящаяПартия.Количество;
			КонецЕсли;

			controlIdentificationMarkBefore = xmlСоздатьДочернийЭлементXDTO(lineItem, "controlIdentificationMarksBefore");
			controlIdentificationMarkAfter = xmlСоздатьДочернийЭлементXDTO(lineItem, "controlIdentificationMarksAfter");

			Если ПодходящаяПартия.ЭтоВесовойТовар Тогда
				КонтентДо = "02" 
							+ ПодходящаяПартия.GTINКодаМаркировки 
							+ "37" 
							+ Формат(РаспределяемоеКоличествоДо, "ЧДЦ=0; ЧГ=; ЧН=0") 
							+ "3103" 
							+ Формат(РаспределяемыйВесДо,"ЧЦ=9; ЧДЦ=0; ЧВН=; ЧГ=; ЧН=000000000");
				КонтентПосле = "02" 
							+ ПодходящаяПартия.GTINКодаМаркировки 
							+ "37" 
							+ Формат(РаспределяемоеКоличествоПосле, "ЧДЦ=0; ЧГ=; ЧН=0") 
							+ "3103" 
							+ Формат(РаспределяемыйВесПосле,"ЧЦ=9; ЧДЦ=0; ЧВН=; ЧГ=; ЧН=000000000");

				controlIdentificationMarkBefore.type = "MarkingWeightBatches";
				controlIdentificationMarkAfter.type = "MarkingWeightBatches";

			Иначе
				КонтентДо = ПодходящаяПартия.GTINКодаМаркировки;
				КонтентПосле = ПодходящаяПартия.GTINКодаМаркировки;

				controlIdentificationMarkBefore.type = "MarkingBatches";
				controlIdentificationMarkAfter.type = "MarkingBatches";
				//++НЕВ

				Если ЗначениеЗаполнено( СтрокаТоваров.ЕдиницаИзмерения ) Тогда 
					Числитель = ?(СтрокаТоваров.ЕдиницаИзмерения.Числитель=0,1,СтрокаТоваров.ЕдиницаИзмерения.Числитель);
					Знаменатель = ?(СтрокаТоваров.ЕдиницаИзмерения.Знаменатель = 0 , 1, СтрокаТоваров.ЕдиницаИзмерения.Знаменатель);
				Иначе
					Числитель = 1;
					Знаменатель = 1;
				КонецЕсли;

				//--НЕВ				  
				controlIdentificationMarkBefore.quantity = Цел(РаспределяемоеКоличествоДо
					//++НЕВ
					*Числитель/Знаменатель
					//--НЕВ
				);
				controlIdentificationMarkAfter.quantity = Цел(РаспределяемоеКоличествоПосле
					//++НЕВ
					*Числитель/Знаменатель
					//--НЕВ
				);
			КонецЕсли;

			Если Сообщение.Свойство("ВариантНастройкиПартионныйУчет") И Сообщение.ВариантНастройкиПартионныйУчет = "СобиратьИзОтдельныхЧастей" Тогда
				ДатаПроизводства = Формат(ПодходящаяПартия.ДатаПартии, "ДФ=yyMMdd");
				НомерПартии = ПодходящаяПартия.GTINКодаМаркировки + ДатаПроизводства + ПодходящаяПартия.НомерПартии;
			Иначе
				НомерПартии = ПодходящаяПартия.НомерПартии;
			КонецЕсли;

			controlIdentificationMarkBefore.number = НомерПартии;
			controlIdentificationMarkAfter.number = НомерПартии;

			controlIdentificationMarkBefore.__content = КонтентДо;
			controlIdentificationMarkAfter.__content = КонтентПосле;

			ПодходящаяПартия.КоличествоДоКорректировки = ПодходящаяПартия.КоличествоДоКорректировки - РаспределяемоеКоличествоДо;
			ПодходящаяПартия.Количество = ПодходящаяПартия.Количество - РаспределяемоеКоличествоПосле;

			НеобходимоеКоличествоТовараДоКорректировки = НеобходимоеКоличествоТовараДоКорректировки - РаспределяемоеКоличествоДо;
			НеобходимоеКоличествоТовараПослеКорректировки = НеобходимоеКоличествоТовараПослеКорректировки - РаспределяемоеКоличествоПосле;

			Если ПодходящаяПартия.КоличествоДоКорректировки <= 0 И ПодходящаяПартия.Количество <= 0 Тогда
				Сообщение.НомераПартий.Удалить(ПодходящаяПартия);	
			КонецЕсли;

			Если НеобходимоеКоличествоТовараДоКорректировки <= 0 И НеобходимоеКоличествоТовараПослеКорректировки <= 0 Тогда
				Прервать;
			КонецЕсли;

		КонецЦикла;

	КонецЕсли;

КонецЕсли;

// Описание:
// 	Исполняется перед запуском ЗаписатьXML фабрикиXDTO.
// 	Можно переопределить заполнение EdiMessage при использовании XDTO на исходящих сообщениях..
// 
// Параметры:
// 	EdiMessage - ЗначениеXDTO - ОбъектXDTO, полученный как правило с помощью СоздатьПустойОбъектXDTO() и (в зависимости от события!) заполненный или нет.
// 	Сообщение - Структура - Сообщение EDI в представлении 1С.

Сообщение = Параметры.Сообщение;

Если Сообщение.ТипСообщения = "INVOIC" ИЛИ Сообщение.ТипСообщения = "COINVOIC" Тогда

	//При формировании lineItem таблица номеров партий будет модифицироваться, поэтому необходимо сохранить её копию и затем восстановить после заполнения xml
	Если Сообщение.Свойство("НомераПартий") Тогда

		ПараметрыСобытия = Новый Структура("Сообщение", Сообщение);
		ОбработкаСобытияПодключаемогоМодуля("ЗаполнитьGTINПартий_BatchMarking_UPD970",,ПараметрыСобытия);

		Сообщение.Вставить("НомераПартийКопия", Сообщение.НомераПартий.Скопировать());

	КонецЕсли;

	Если Сообщение.Свойство("НомераПартийПредыдущегоСообщения") Тогда
	    Сообщение.Вставить("НомераПартийПредыдущегоСообщенияКопия", Сообщение.НомераПартийПредыдущегоСообщения.Скопировать());
	КонецЕсли;

	НастройкиРасширения = ОбработкаСобытияПодключаемогоМодуля("НастройкиРасширения_BatchMarking_UPD970");
	Сообщение.Вставить("ВариантНастройкиПартионныйУчет", НастройкиРасширения.ВариантНастройки);

КонецЕсли;

// Описание:
// 	Исполняется после заполнения секции lineItem - одной строки товаров.
// 	Можно переопределить заполнение при использовании XDTO на исходящих сообщениях..
// 
// Параметры:
// 	lineItem - ЗначениеXDTO - ОбъектXDTO - строка товаров.
// 	Сообщение - Структура - Сообщение EDI в представлении 1С.
// 	СтрокаТоваров - Нет данных - Элемент ТЗ: Сообщение.Товары.
Сообщение = Параметры.Сообщение;
EDIMessage = Параметры.EdiMessage;

Если Сообщение.ТипСообщения = "INVOIC" ИЛИ Сообщение.ТипСообщения = "COINVOIC" Тогда 

	Если Сообщение.Свойство("НомераПартийКопия") Тогда
		Сообщение.НомераПартий = Сообщение.НомераПартийКопия.Скопировать();
		Сообщение.Удалить("НомераПартийКопия");
	КонецЕсли;

	Если Сообщение.Свойство("НомераПартийПредыдущегоСообщенияКопия") Тогда
		Сообщение.НомераПартийПредыдущегоСообщения = Сообщение.НомераПартийПредыдущегоСообщенияКопия.Скопировать();
		Сообщение.Удалить("НомераПартийПредыдущегоСообщенияКопия");
	КонецЕсли;

КонецЕсли;

Если Сообщение.ТипСообщения = "INVOIC" 
	И Сообщение.Свойство("ТипыМаркируемойПродукции")
	И Сообщение.Свойство("НомераПартий")
	И ЗначениеЗаполнено(Сообщение.НомераПартий)
	И EDIMessage.invoice.goodsMarkTypes.Количество() = 0 Тогда

	Если Сообщение.ТипыМаркируемойПродукции.НайтиПоЗначению("Mark") = Неопределено Тогда
		Сообщение.ТипыМаркируемойПродукции.Добавить("Mark", "Товары, подлежащие маркировке");
	КонецЕсли;

	xmlЗаполнитьЗначениеXDTO(EDIMessage.invoice, "goodsMarkTypes", Сообщение.ТипыМаркируемойПродукции); 

КонецЕсли;

Если Сообщение.ТипСообщения = "COINVOIC"
	И Сообщение.Свойство("ТипыМаркируемойПродукции")
	И Сообщение.Свойство("НомераПартий")
	И ЗначениеЗаполнено(Сообщение.НомераПартий)
	И EDIMessage.correctiveInvoice.goodsMarkTypes.Количество() = 0
	И ОбработкаСобытияПодключаемогоМодуля("COINVOICвФорматеУКД29_BatchMarking_UPD970") Тогда

	Если Сообщение.ТипыМаркируемойПродукции.НайтиПоЗначению("Mark") = Неопределено Тогда
		Сообщение.ТипыМаркируемойПродукции.Добавить("Mark", "Товары, подлежащие маркировке");
	КонецЕсли;

	xmlЗаполнитьЗначениеXDTO(EDIMessage.correctiveInvoice, "goodsMarkTypes", Сообщение.ТипыМаркируемойПродукции); 

КонецЕсли;

// Описание:
// 	Позволяет выполнять произвольные действия с формой сообщения перед ее открытием. Форма уже будет заполнена информацией из Структуры «Сообщение»..
//
// Параметры:
// 	Сообщение - Структура - Сообщение EDI в представлении 1С.
// 	ФормаСообщения - Нет данных - Описание параметра находится в разработке.
Сообщение = Параметры.Сообщение;
Форма = Параметры.ФормаСообщения;

Если Сообщение.ТипСообщения = "INVOIC" Или Сообщение.ТипСообщения = "COINVOIC" Тогда

	ПараметрыСобытия = Новый Структура("Сообщение", Сообщение);
	ОбработкаСобытияПодключаемогоМодуля("ЗаполнитьGTINПартий_BatchMarking_UPD970",,ПараметрыСобытия);

	КнопкаКоманда = Неопределено;

	ЭтоУФ = Ложь;
	Если Лев(ОсновнойМодуль.ИмяКонфигурации1С, 3) = "УФ_" Тогда
		ЭтоУФ = Истина;
	КонецЕсли;

	ИмяКнопки = "ПоказатьКодыПартионногоУчета";
	СинонимКнопки = "Коды партионного учета";

	Если ЭтоУФ Тогда
		КнопкаКоманда = Форма.Команды.Найти(ИмяКнопки);
	Иначе
		КнопкаКоманда = Форма.ЭлементыФормы.ОсновныеДействияФормы.Кнопки.Найти(ИмяКнопки);
	КонецЕсли;

	Если КнопкаКоманда = Неопределено Тогда

		ДобавитьКнопкуКоманднойПанелиПодключаемыйМодуль(
				Форма, 
				ИмяКнопки, 
				СинонимКнопки,
				БиблиотекаКартинок.Документ);

		Если ЭтоУФ Тогда

			ДобавляемыеРеквизиты = Новый Массив; 
			НовыйРеквизит = Новый РеквизитФормы("РасширениеКодыПартионногоУчета",Новый ОписаниеТипов("СправочникСсылка.КонтурEDI_ДополнительныеСправочники"));
			ДобавляемыеРеквизиты.Добавить(НовыйРеквизит);

			Форма.ИзменитьРеквизиты(ДобавляемыеРеквизиты); 

			Запрос = Новый Запрос;
			Запрос.Текст =
			"ВЫБРАТЬ
			|	КонтурEDI_ДополнительныеСправочники.Ссылка КАК Ссылка
			|ИЗ
			|	Справочник.КонтурEDI_ДополнительныеСправочники КАК КонтурEDI_ДополнительныеСправочники
			|ГДЕ
			|	КонтурEDI_ДополнительныеСправочники.Наименование = ""Коды маркировки — партионный учет""
			|	И КонтурEDI_ДополнительныеСправочники.ИмяСправочника = ""Расширения""
			|	И НЕ КонтурEDI_ДополнительныеСправочники.ПометкаУдаления";

			РезультатЗапроса = Запрос.Выполнить();

			ВыборкаДетальныеЗаписи = РезультатЗапроса.Выбрать();

			Если ВыборкаДетальныеЗаписи.Следующий() Тогда
				Форма.РасширениеКодыПартионногоУчета = ВыборкаДетальныеЗаписи.Ссылка;
			КонецЕсли;

		КонецЕсли;
	КонецЕсли;		
КонецЕсли;

// Описание:
// 	Для описания клиентских действий при нажатии на добавленную кнопку..
// 
// Параметры:
// 	ИмяКоманды - Строка - Имя команды.
// 	Сообщение - Структура - Сообщение EDI в представлении 1С.
// 	Параметры -  - Параметры.
// 	Форма - Нет данных - Форма. Обычная или управляемая..
// 	СтандартнаяОбработкаEDI - Булево - флаг стандартной обработки.
// 
// Возвращаемое значение:
// 	Булево
// 	Признак обработана ли строка действия.
Если Команда.Имя = "ПоказатьКодыПартионногоУчета" И ЗначениеЗаполнено(ЭтаФорма.РасширениеКодыПартионногоУчета) Тогда

	ПодключаемоеРасширение = Новый Структура("РасширениеСсылка", ЭтаФорма.РасширениеКодыПартионногоУчета);   	
	ИмяПодключеннойОбработки = МодульОбъектаКлиент().ВыполнитьМетодМодуляОбъекта("Функция", "ПодключитьИнтерфейсРасширения", ПодключаемоеРасширение);

	Если ЗначениеЗаполнено(ИмяПодключеннойОбработки) Тогда

		ПараметрыОткрытия = Новый Структура;
		ПараметрыОткрытия.Вставить("КлючВарианта", "");
		ПараметрыОткрытия.Вставить("ОбработкаОбъект", ЭтаФорма.Объект);
		ПараметрыОткрытия.Вставить("АдресВХПроизвольныеРеквизиты", ЭтаФорма.АдресВХПроизвольныеРеквизиты);
		ПараметрыОткрытия.Вставить("Сообщение", ЭтаФорма.Сообщение);

		Уникальность = "ВнешняяОбработка." + ИмяПодключеннойОбработки + "/КлючВарианта.";
    	ОткрытьФорму("ВнешняяОбработка." + ИмяПодключеннойОбработки + ".Форма.ФормаПросмотраКодовПартионногоУчета", ПараметрыОткрытия, ЭтаФорма, Уникальность)

	КонецЕсли;

ИначеЕсли Команда.Имя = "ОткрытьДетальныеНастройкиПартионныйУчет" И ЗначениеЗаполнено(ЭтаФорма.РасширениеКодыПартионногоУчета) Тогда

	ПодключаемоеРасширение = Новый Структура("РасширениеСсылка", ЭтаФорма.РасширениеКодыПартионногоУчета);   	
	ИмяПодключеннойОбработки = МодульОбъектаКлиент().ВыполнитьМетодМодуляОбъекта("Функция", "ПодключитьИнтерфейсРасширения", ПодключаемоеРасширение);

	Если ЗначениеЗаполнено(ИмяПодключеннойОбработки) Тогда

		ДанныеВыбраннойСтроки = Элементы.СписокНоменклатуры.ТекущиеДанные;

		Если ДанныеВыбраннойСтроки = Неопределено Тогда 
			Если ЭтаФорма.СписокНоменклатуры.Количество() = 1 Тогда
				ДанныеВыбраннойСтроки = ЭтаФорма.СписокНоменклатуры[0];
			ИначеЕсли ЭтаФорма.СписокНоменклатуры.Количество() > 1 Тогда
				Сообщить("Выберите строку номенклатуры для открытия настроек партионного учета");
			Иначе
				ДанныеВыбраннойСтроки = Неопределено;
			КонецЕсли;
		КонецЕсли;

		Если Не ДанныеВыбраннойСтроки = Неопределено Тогда

			ПараметрыОткрытия = Новый Структура("КлючВарианта, ОбработкаОбъект", "", Объект);

			ПараметрыОткрытия.Вставить("Номенклатура", ДанныеВыбраннойСтроки.Номенклатура);
			ПараметрыОткрытия.Вставить("ХарактеристикаНоменклатуры", ДанныеВыбраннойСтроки.ХарактеристикаНоменклатуры);
			ПараметрыОткрытия.Вставить("ЕдиницаИзмерения", ДанныеВыбраннойСтроки.ЕдиницаИзмерения);

			Уникальность = "ВнешняяОбработка." + ИмяПодключеннойОбработки + "/КлючВарианта.";
			ОткрытьФорму("ВнешняяОбработка." + ИмяПодключеннойОбработки + ".Форма.ФормаДетальнойНастройкиНоменклатуры_Управляемая", ПараметрыОткрытия, ЭтаФорма, Уникальность);

		КонецЕсли;

	КонецЕсли;

КонецЕсли;

// Описание:
// 	Позволяет определять или переопределять действия кнопок на панели действий формы сообщений. См. пример в инструкции для разработчика..
// 
// Параметры:
// 	ИмяКнопки - Нет данных - Описание параметра находится в разработке.
// 	Сообщение - Структура - Сообщение EDI в представлении 1С.
// 	Параметры - Нет данных - Описание параметра находится в разработке.
// 	РезультатКлиента - Произвольный - СЕРИАЛИЗУЕМЫЙ!!!	Позволяет передать в серверный обработчик результат кастомной обработки на клиенте.
// 	СтандартнаяОбработкаEDI - Булево - флаг стандартной обработки.

Если НЕ Параметры.Свойство("ИмяКоманды")
	И Параметры.ИмяКнопки = "ПоказатьКодыПартионногоУчета" Тогда

	Сообщение = Параметры.Сообщение;

	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	КонтурEDI_ДополнительныеСправочники.Ссылка КАК Ссылка
	|ИЗ
	|	Справочник.КонтурEDI_ДополнительныеСправочники КАК КонтурEDI_ДополнительныеСправочники
	|ГДЕ
	|	КонтурEDI_ДополнительныеСправочники.Наименование = ""Коды маркировки — партионный учет""
	|	И КонтурEDI_ДополнительныеСправочники.ИмяСправочника = ""Расширения""
	|	И НЕ КонтурEDI_ДополнительныеСправочники.ПометкаУдаления";

	РезультатЗапроса = Запрос.Выполнить();

	ВыборкаДетальныеЗаписи = РезультатЗапроса.Выбрать();

	Если ВыборкаДетальныеЗаписи.Следующий() Тогда

		РезультатПолучения = ПолучитьИнтерфейсРасширения(ВыборкаДетальныеЗаписи.Ссылка);	
		Если РезультатПолучения.Успешно Тогда

			Интерфейс = РезультатПолучения.Интерфейс;	

			//открываем интерфейс
			Попытка
				ФормаИнтерфейса = Интерфейс.ПолучитьФорму("ФормаПросмотраКодовПартионногоУчетаОФ", Параметры.Форма);

				ПараметрыОткрытия = Новый Структура();
				ПараметрыОткрытия.Вставить("Сообщение", Сообщение);
				ФормаИнтерфейса.ПараметрыОткрытия = ПараметрыОткрытия;

				ФормаИнтерфейса.ОткрытьМодально();

			Исключение
				Сообщить("Не удалось открыть интерфейс настройки расширения. " + ОписаниеОшибки());
			КонецПопытки;

		КонецЕсли; 	

	КонецЕсли;

КонецЕсли;

Запрос = Новый Запрос;
Если ИмяКонфигурации1С = "УФ_УТ" Тогда
Запрос.Текст = "ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ | Штрихкоды.Номенклатура КАК Номенклатура, | Штрихкоды.Характеристика КАК ХарактеристикаНоменклатуры, | Штрихкоды.Штрихкод КАК Штрихкод |ИЗ | РегистрСведений.ШтрихкодыНоменклатуры КАК Штрихкоды |ГДЕ | Штрихкоды.Номенклатура В (&Номенклатура) | И (Штрихкоды.Упаковка = Штрихкоды.Номенклатура.ЕдиницаИзмерения | ИЛИ Штрихкоды.Упаковка = ЗНАЧЕНИЕ(Справочник.УпаковкиНоменклатуры.ПустаяСсылка))";
Если ОсновнойМодуль.ЕстьНеобходимыеМетаданные("Справочники.УпаковкиЕдиницыИзмерения") Тогда Запрос.Текст = СтрЗаменить(Запрос.Текст, "УпаковкиНоменклатуры", "УпаковкиЕдиницыИзмерения"); КонецЕсли;
ИначеЕсли ИмяКонфигурации1С = "УФ_БП" Тогда
Запрос.Текст = "ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ | ШтрихкодыНоменклатуры.Номенклатура КАК Номенклатура, | НЕОПРЕДЕЛЕНО КАК ХарактеристикаНоменклатуры, | ШтрихкодыНоменклатуры.Штрихкод КАК Штрихкод |ИЗ | РегистрСведений.ШтрихкодыНоменклатуры КАК ШтрихкодыНоменклатуры |ГДЕ | ШтрихкодыНоменклатуры.Номенклатура В(&Номенклатура)";
ИначеЕсли ИмяКонфигурации1С = "УФ_УНФ" Тогда
Запрос.Текст = "ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ | ШтрихкодыНоменклатуры.Номенклатура КАК Номенклатура, | ШтрихкодыНоменклатуры.Характеристика КАК ХарактеристикаНоменклатуры, | ШтрихкодыНоменклатуры.Штрихкод КАК Штрихкод |ИЗ | РегистрСведений.ШтрихкодыНоменклатуры КАК ШтрихкодыНоменклатуры |ГДЕ | ШтрихкодыНоменклатуры.Номенклатура В (&Номенклатура) | И (ШтрихкодыНоменклатуры.ЕдиницаИзмерения = ШтрихкодыНоменклатуры.Номенклатура.ЕдиницаИзмерения | ИЛИ ШтрихкодыНоменклатуры.ЕдиницаИзмерения = ЗНАЧЕНИЕ(Справочник.ЕдиницыИзмерения.ПустаяСсылка))";
ИначеЕсли ИмяКонфигурации1С = "ТКПТ" Тогда
Запрос.Текст = "ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ | Штрихкоды.Объект КАК Номенклатура, | Штрихкоды.ХарактеристикаНоменклатуры, | Штрихкоды.ОсновнойШтрихкод КАК Штрихкод |ИЗ | РегистрСведений.Штрихкоды КАК Штрихкоды |ГДЕ | Штрихкоды.Объект В (&Номенклатура) | И (Штрихкоды.ЕдиницаИзмерения = Штрихкоды.Объект.ОсновнаяЕдиницаИзмерения | ИЛИ Штрихкоды.ЕдиницаИзмерения = ЗНАЧЕНИЕ(Справочник.ЕдиницыИзмерения.ПустаяСсылка))";
ИначеЕсли ИмяКонфигурации1С = "УФ_Розница" Тогда
Запрос.Текст = "ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ | Штрихкоды.Владелец КАК Номенклатура, | Штрихкоды.Характеристика КАК ХарактеристикаНоменклатуры, | Штрихкоды.Штрихкод КАК Штрихкод |ИЗ | РегистрСведений.Штрихкоды КАК Штрихкоды |ГДЕ | Штрихкоды.Владелец В (&Номенклатура) | И (Штрихкоды.Упаковка = Штрихкоды.Владелец.ЕдиницаИзмерения | ИЛИ Штрихкоды.Упаковка = ЗНАЧЕНИЕ(Справочник.УпаковкиНоменклатуры.ПустаяСсылка))";
ИначеЕсли ИмяКонфигурации1С = "КА" ИЛИ ИмяКонфигурации1С = "УПП" ИЛИ ИмяКонфигурации1С = "УТ_10_2" ИЛИ ИмяКонфигурации1С = "УТ_10_3" Тогда
Запрос.Текст = "ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ | Штрихкоды.Владелец КАК Номенклатура, | Штрихкоды.ХарактеристикаНоменклатуры, | Штрихкоды.Штрихкод КАК Штрихкод |ИЗ | РегистрСведений.Штрихкоды КАК Штрихкоды |ГДЕ | Штрихкоды.Владелец В(&Номенклатура) | И (Штрихкоды.ЕдиницаИзмерения = Штрихкоды.Владелец.ЕдиницаХраненияОстатков | ИЛИ Штрихкоды.ЕдиницаИзмерения = ЗНАЧЕНИЕ(Справочник.ХарактеристикиНоменклатуры.ПустаяСсылка))";
Иначе
//Область для доработки своего запроса по штрихкодам //В запросе необходимо обязательно возвращать поля "Номенклатура", "ХарактеристикаНоменклатуры", "Штрихкод" //В параметр "Номенклатура" передается массив номенклатуры 1С из сообщения
КонецЕсли;
Если ЗначениеЗаполнено(Запрос.Текст) Тогда
МассивНоменклатуры = Параметры.МассивНоменклатуры; Запрос.УстановитьПараметр("Номенклатура", МассивНоменклатуры);
Результат = Запрос.Выполнить().Выгрузить(); //++НЕВ Для Каждого сРезультат из Результат Цикл
Если СтрДлина(сРезультат.Штрихкод) > 13 Тогда сРезультат.Штрихкод = Лев(сРезультат.Штрихкод,13); КонецЕсли;
КонецЦикла;
//--НЕВ Иначе
Результат = Новый ТаблицаЗначений;
КонецЕсли;
Возврат Результат;

СтрокаТоваров = Параметры.СтрокаТоваров;
ТаблицаШтрихкодов = Параметры.ТаблицаШтрихкодов;

ПодобранныеШтрихкоды = Новый Массив;

Если ЗначениеЗаполнено(СтрокаТоваров.СписокНоменклатуры) Тогда
	Для каждого ЭлементСписка Из СтрокаТоваров.СписокНоменклатуры Цикл
		СтруктураПоиска = Новый Структура;
		СтруктураПоиска.Вставить("Номенклатура", ЭлементСписка.Значение);
		ПодобранныеШтрихкоды = ТаблицаШтрихкодов.НайтиСтроки(СтруктураПоиска);
		Если ПодобранныеШтрихкоды.Количество() > 0 Тогда
			Прервать;
		КонецЕсли;
	КонецЦикла;
КонецЕсли;

СтруктураПоиска = Новый Структура("Номенклатура, ХарактеристикаНоменклатуры");

Если ПодобранныеШтрихкоды.Количество() = 0 Тогда 
	ЗаполнитьЗначенияСвойств(СтруктураПоиска, СтрокаТоваров);
	ПодобранныеШтрихкоды = ТаблицаШтрихкодов.НайтиСтроки(СтруктураПоиска);
КонецЕсли;

Если ПодобранныеШтрихкоды.Количество() = 0 Тогда
	ПустаяСсылкаХарактеристики = ПолучитьПустуюСсылкуОбъекта("ХарактеристикаНоменклатуры");
	Если Не ПустаяСсылкаХарактеристики = Неопределено Тогда
		СтруктураПоиска.ХарактеристикаНоменклатуры = ПустаяСсылкаХарактеристики;
		ПодобранныеШтрихкоды = ТаблицаШтрихкодов.НайтиСтроки(СтруктураПоиска);
	КонецЕсли;
КонецЕсли;

Если ПодобранныеШтрихкоды.Количество() = 0 Тогда
	СтруктураПоиска.Удалить("ХарактеристикаНоменклатуры");
	ПодобранныеШтрихкоды = ТаблицаШтрихкодов.НайтиСтроки(СтруктураПоиска);
КонецЕсли;

Если ПодобранныеШтрихкоды.Количество() > 0 Тогда
	Возврат ПодобранныеШтрихкоды[0].Штрихкод;
Иначе
	Возврат Неопределено;
КонецЕсли;

ИмяФайлаДляОтладки = Неопределено;
ИнтерфейсРасширения = Неопределено;
//++НЕВ
//ИмяФайлаДляОтладки = "\\NEO-OFFICE-DC03\Shared_temp\Temp\контур\ЕДИ_НЕО\1__BatchMarking_UPD970\interface.epf";
//--НЕВ
Если ИмяФайлаДляОтладки = Неопределено Тогда
	РезультатПолучения = ПолучитьИнтерфейсРасширения(РасширениеСсылка);	
	ИнтерфейсРасширения = РезультатПолучения.Интерфейс;
Иначе
	ИнтерфейсРасширения = ВнешниеОбработки.Создать(СокрЛП(ИмяФайлаДляОтладки), Ложь);
КонецЕсли;

Возврат ИнтерфейсРасширения;

НастройкиРасширения = ЭДО_Кэш_Прочитать("НастройкиРасширения_BatchMarking_UPD970");

Если НастройкиРасширения = Неопределено Тогда

	ИнтерфейсРасширения = ОбработкаСобытияПодключаемогоМодуля("ИнтерфейсРасширения_BatchMarking_UPD970");
	НастройкиРасширения = ИнтерфейсРасширения.ЗагрузитьНастройкиРасширения();

	ЭДО_Кэш_Поместить("НастройкиРасширения_BatchMarking_UPD970", НастройкиРасширения);

КонецЕсли;

Возврат НастройкиРасширения;

// Описание:
// 	Позволяет выполнять произвольные действия с формой сообщения перед ее открытием. Форма уже будет заполнена информацией из Структуры «Сообщение»..
// 
// Параметры:
// 	Форма_Номенклатуры - Нет данных - Описание параметра находится в разработке.

Форма_Номенклатуры = Параметры.Форма_Номенклатуры;

КнопкаКоманда = Неопределено;

ЭтоУФ = Ложь;
Если Лев(ОсновнойМодуль.ИмяКонфигурации1С, 3) = "УФ_" Тогда
	ЭтоУФ = Истина;		
КонецЕсли;

ИмяКнопки = "ОткрытьДетальныеНастройкиПартионныйУчет";
СинонимКнопки = "Настройки партионного учета";

Если ЭтоУФ Тогда
	КнопкаКоманда = Форма_Номенклатуры.Команды.Найти(ИмяКнопки);
Иначе
	КнопкаКоманда = Форма_Номенклатуры.ЭлементыФормы.КоманднаяПанель1.Кнопки.Найти(ИмяКнопки);
КонецЕсли;        	

Если ЭтоУФ И КнопкаКоманда = Неопределено Тогда

	Команда = Форма_Номенклатуры.Команды.Добавить(ИмяКнопки);
	Команда.Действие 	= "АкцепторДобавленнойКнопки";
	Команда.Заголовок 	= СинонимКнопки;
	Команда.Отображение	= ОтображениеКнопки.КартинкаИТекст;
	Команда.Картинка 	= БиблиотекаКартинок.Найти;
	НоваяКнопка = Форма_Номенклатуры.Элементы.Добавить(Команда.Имя, Тип("КнопкаФормы"), Форма_Номенклатуры.КоманднаяПанель); // .ПодчиненныеЭлементы.ДополнительныеДействияФормы
	НоваяКнопка.ИмяКоманды = Команда.Имя;

	ДобавляемыеРеквизиты = Новый Массив; //Определяем массив добавляемых реквизитов
	НовыйРеквизит = Новый РеквизитФормы("РасширениеКодыПартионногоУчета",Новый ОписаниеТипов("СправочникСсылка.КонтурEDI_ДополнительныеСправочники")); 
	ДобавляемыеРеквизиты.Добавить(НовыйРеквизит); 

	Параметры.Форма_Номенклатуры.ИзменитьРеквизиты(ДобавляемыеРеквизиты); //Применяем реквизиты

	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	КонтурEDI_ДополнительныеСправочники.Ссылка КАК Ссылка
	|ИЗ
	|	Справочник.КонтурEDI_ДополнительныеСправочники КАК КонтурEDI_ДополнительныеСправочники
	|ГДЕ
	|	КонтурEDI_ДополнительныеСправочники.Наименование = ""Коды маркировки — партионный учет""
	|	И КонтурEDI_ДополнительныеСправочники.ИмяСправочника = ""Расширения""
	|	И НЕ КонтурEDI_ДополнительныеСправочники.ПометкаУдаления";

	РезультатЗапроса = Запрос.Выполнить();

	ВыборкаДетальныеЗаписи = РезультатЗапроса.Выбрать();

	Если ВыборкаДетальныеЗаписи.Следующий() Тогда
		Параметры.Форма_Номенклатуры.РасширениеКодыПартионногоУчета = ВыборкаДетальныеЗаписи.Ссылка;	
	КонецЕсли;

ИначеЕсли КнопкаКоманда = Неопределено Тогда

	АлгоритмДобавленияКнопки = "
	|ДействиеКнопки 			= Новый Действие(""АкцепторСобытий1Параметр"");
	|КнопкиСписка 			= Параметры.Форма_Номенклатуры.ЭлементыФормы.КоманднаяПанель1.Кнопки;
	|НоваяКнопка 			= КнопкиСписка.Добавить(""ОткрытьДетальныеНастройкиПартионныйУчет"", ТипКнопкиКоманднойПанели.Действие, ""Настройки партионного учета"", ДействиеКнопки);
	|НоваяКнопка.Картинка 	= БиблиотекаКартинок.Найти;
	|НоваяКнопка.Отображение = ОтображениеКнопкиКоманднойПанели.НадписьКартинка;
	|КоличествоКнопок 		= КнопкиСписка.Количество();
	|КнопкиСписка.Сдвинуть(КнопкиСписка[КоличествоКнопок-1],-КоличествоКнопок+1);";
	Выполнить(АлгоритмДобавленияКнопки);

КонецЕсли;

Сообщение = Параметры.Сообщение;
ТаблицаОшибок = Параметры.ТаблицаОшибок;

Если Сообщение.ТипСообщения = "INVOIC" И Сообщение.Направление = "Исходящее" Тогда

	ПараметрыСобытия = Новый Структура("Сообщение", Сообщение);
	ОбработкаСобытияПодключаемогоМодуля("ЗаполнитьGTINПартий_BatchMarking_UPD970",,ПараметрыСобытия);

	НастройкиРасширения = ОбработкаСобытияПодключаемогоМодуля("НастройкиРасширения_BatchMarking_UPD970");
	ОграничениеНаКоличествоСимволов = 55;

	Для каждого Партия Из Сообщение.НомераПартий Цикл

		Номенклатура = Партия.Номенклатура;

		Если Не ЗначениеЗаполнено(Партия.НомерПартии) и Партия.ДатаПартии <> Неопределено и  Партия.ДатаПартии > '20261101' Тогда
			ТекстОшибки = "Обнаружен пустой номер партии в коде партионного учета у номенклатуры " + Номенклатура;
			ЗафиксироватьОшибку(ТаблицаОшибок, , , , ТекстОшибки, Истина);
		КонецЕсли;  

		Если СтрДлина(Партия.НомерПартии) > ОграничениеНаКоличествоСимволов и Партия.ДатаПартии <> Неопределено и Партия.ДатаПартии > '20261101' Тогда
			ТекстОшибки = "Номер партии кода партионного учета превышает допустимую длину (" + ОграничениеНаКоличествоСимволов + " символов). Номенклатура: " + Номенклатура;
			ЗафиксироватьОшибку(ТаблицаОшибок, , , , ТекстОшибки, Истина);
		КонецЕсли;

		Если Не ЗначениеЗаполнено(Партия.GTINКодаМаркировки) Тогда
			ТекстОшибки = "Не удалось определить GTIN для кода партионного учета. Номенклатура: " + Номенклатура + ", номер партии: " + Партия.НомерПартии;
			ЗафиксироватьОшибку(ТаблицаОшибок, , , , ТекстОшибки, Истина);
		КонецЕсли;

		Если НастройкиРасширения.ВариантНастройки = "СобиратьИзОтдельныхЧастей" И НастройкиРасширения.БлокироватьОтправкуСообщенияПриОшибке = Истина Тогда

			Если Не ЗначениеЗаполнено(Партия.ДатаПартии) Тогда
				ТекстОшибки = "Не удалось определить дату производства партии для кода партионного учета. Номенклатура: " + Номенклатура + ", номер партии: " + Партия.НомерПартии;
				ЗафиксироватьОшибку(ТаблицаОшибок, , , , ТекстОшибки, Истина);
			КонецЕсли;

			ДлинаДаты = 6;
			ДлинаGTIN = 14;
			ОбщаяДлинаПартии = СтрДлина(Партия.НомерПартии) + ДлинаДаты + ДлинаGTIN;
			Если ОбщаяДлинаПартии > ОграничениеНаКоличествоСимволов Тогда
				ТекстОшибки = "Сгенерированный номер партии кода партионного учета превышает допустимую длину (" + ОграничениеНаКоличествоСимволов + " символов). Номенклатура: " + Номенклатура;
				ЗафиксироватьОшибку(ТаблицаОшибок, , , , ТекстОшибки, Истина);
			КонецЕсли;

		КонецЕсли;

	КонецЦикла;

КонецЕсли;

Сообщение = Параметры.Сообщение;
НужноЗаполнятьGTIN = Сообщение.НомераПартий.Найти("", "GTINКодаМаркировки") <> Неопределено;

Если НужноЗаполнятьGTIN Тогда

	ПолеКодовМаркировки = "КодыМаркировки";
	Если Сообщение.ТипСообщения = "COINVOIC" Тогда
		ПолеКодовМаркировки = "КодыМаркировкиПосле";
	КонецЕсли;

	ЕстьGTINНацКаталога = Сообщение.Товары.Колонки.Найти("GTINНацКаталога") <> Неопределено;

	НоменклатураСообщения = ОбработкаСобытияПодключаемогоМодуля("ПолучитьНоменклатуруСообщения_BatchMarking_UPD970",,Новый Структура("Сообщение", Сообщение));
	ПараметрыСобытия = Новый Структура("МассивНоменклатуры", НоменклатураСообщения);
	ТаблицаШтрихкодов = ОсновнойМодуль.ОбработкаСобытияПодключаемогоМодуля("ПолучитьТаблицуШтрихкодов_BatchMarking_UPD970",,ПараметрыСобытия);

	GTINИзКодовОСУ = Новый Соответствие;

	Для каждого СтрокаТоваров Из Сообщение.Товары Цикл

		GTINСтроки = Неопределено;

		//GTIN из кодов ОСУ, которые могли быть заполнены ранее
		Если ЗначениеЗаполнено(СтрокаТоваров[ПолеКодовМаркировки]) Тогда
			Для каждого КодМаркировки Из СтрокаТоваров[ПолеКодовМаркировки] Цикл
				Код = КодМаркировки.Значение;
				ЭтоКодОСУ = СтрДлина(Код) > 18 И Лев(Код, 2) = "02" И Сред(Код, 17, 2) = "37";
				Если ЭтоКодОСУ Тогда
					GTINСтроки = Сред(Код, 3, 14);
					Прервать;
				КонецЕсли;
			КонецЦикла;
		КонецЕсли;

		Если GTINСтроки = Неопределено 
			И ЕстьGTINНацКаталога 
			И ЗначениеЗаполнено(СтрокаТоваров.GTINНацКаталога) Тогда

			GTINСтроки = СтрокаТоваров.GTINНацКаталога;

		КонецЕсли;

		//Ниже попытка получить GTIN из штрихкодов номенклатуры
		Если GTINСтроки = Неопределено Тогда
			ПараметрыСобытия = Новый Структура;
			ПараметрыСобытия.Вставить("ТаблицаШтрихкодов", ТаблицаШтрихкодов);
			ПараметрыСобытия.Вставить("СтрокаТоваров", СтрокаТоваров);
			GTINСтроки = ОсновнойМодуль.ОбработкаСобытияПодключаемогоМодуля("ПодобратьШтрихкод_BatchMarking_UPD970",,ПараметрыСобытия);
		КонецЕсли;

		Если GTINСтроки = Неопределено Тогда
			//Не удалось определить GTIN для текущей номенклатуры
			Продолжить;
		КонецЕсли;

		Для каждого СвернутаяНоменклатура Из СтрокаТоваров.СписокНоменклатуры Цикл
			GTINИзКодовОСУ.Вставить(СвернутаяНоменклатура.Значение, GTINСтроки);	
		КонецЦикла;

		Если ЗначениеЗаполнено(СтрокаТоваров.Номенклатура) Тогда

			GTINИзКодовОСУ.Вставить(СтрокаТоваров.Номенклатура, GTINСтроки);

			Если ЗначениеЗаполнено(СтрокаТоваров.ХарактеристикаНоменклатуры) Тогда
				ПолныйКлючСтроки = Строка(СтрокаТоваров.Номенклатура.УникальныйИдентификатор()) 
									+ Строка(СтрокаТоваров.ХарактеристикаНоменклатуры.УникальныйИдентификатор());
				GTINИзКодовОСУ.Вставить(ПолныйКлючСтроки, GTINСтроки);
			КонецЕсли;

		КонецЕсли;

	КонецЦикла;

	Для каждого СтрокаПартии Из Сообщение.НомераПартий Цикл

		Если ЗначениеЗаполнено(СтрокаПартии.GTINКодаМаркировки) Тогда
			Продолжить;
		КонецЕсли;

		GTINСтроки = Неопределено;

		Если ЗначениеЗаполнено(СтрокаПартии.ХарактеристикаНоменклатуры) Тогда
			ПолныйКлючСтрокиПоиска = Строка(СтрокаПартии.Номенклатура.УникальныйИдентификатор()) 
										+ Строка(СтрокаПартии.ХарактеристикаНоменклатуры.УникальныйИдентификатор()); 
			GTINСтроки = GTINИзКодовОСУ.Получить(ПолныйКлючСтрокиПоиска);
		КонецЕсли;

		Если GTINСтроки = Неопределено Тогда
			GTINСтроки = GTINИзКодовОСУ.Получить(СтрокаПартии.Номенклатура);
		КонецЕсли;

		Если ЗначениеЗаполнено(GTINСтроки) Тогда 
			СтрокаПартии.GTINКодаМаркировки = Прав("000000000000000" + GTINСтроки, 14);
		КонецЕсли;

	КонецЦикла;

КонецЕсли;

// Описание:
// 	Позволяет определять или переопределять действия кнопок на панели действий формы сообщений. См. пример в инструкции для разработчика..
// 
// Параметры:
// 	ИмяКоманды - Строка - Имя команды.
// 	ИмяКнопки -  - ИмяКнопки.
// 	Форма - Нет данных - Форма. Обычная или управляемая..
// 	РезультатКлиента - Произвольный - СЕРИАЛИЗУЕМЫЙ!!!	Позволяет передать в серверный обработчик результат кастомной обработки на клиенте.
// 	СтандартнаяОбработкаEDI - Булево - флаг стандартной обработки.

Если Параметры.Свойство("ИмяКнопки") И Параметры.ИмяКнопки = "ОткрытьДетальныеНастройкиПартионныйУчет" Тогда

	Форма = Параметры.Форма;
	СтандартнаяОбработкаEDI = Ложь;

	ДанныеВыбраннойСтроки = Форма.ЭлементыФормы.СписокНоменклатуры.ТекущиеДанные;

	Если ДанныеВыбраннойСтроки = Неопределено Тогда 
		Если Форма.СписокНоменклатуры.Количество() = 1 Тогда
			ДанныеВыбраннойСтроки = Форма.СписокНоменклатуры[0];
		ИначеЕсли Форма.СписокНоменклатуры.Количество() > 1 Тогда
			Сообщить("Выберите строку номенклатуры для открытия настроек партионного учета");
		Иначе
			ДанныеВыбраннойСтроки = Неопределено;
		КонецЕсли;
	КонецЕсли;

	Если Не ДанныеВыбраннойСтроки = Неопределено Тогда

		РезультатПолучения = ПолучитьИнтерфейсРасширения(РасширениеСсылка);	
		Если РезультатПолучения.Успешно Тогда

			Интерфейс = РезультатПолучения.Интерфейс;

			ФормаДетальнойНастройки = Интерфейс.ПолучитьФорму("ФормаДетальнойНастройкиНоменклатуры");
			ФормаДетальнойНастройки.Номенклатура = ДанныеВыбраннойСтроки.Номенклатура;
			ФормаДетальнойНастройки.Характеристика = ДанныеВыбраннойСтроки.ХарактеристикаНоменклатуры;
			ФормаДетальнойНастройки.ЕдиницаИзмерения = ДанныеВыбраннойСтроки.ЕдиницаИзмерения;
			ФормаДетальнойНастройки.ОткрытьМодально()

		Иначе
			ВызватьИсключение "Не удалось полуить интерфейс расширения ""Коды маркировки - партионный учет""";
		КонецЕсли;
	КонецЕсли;
КонецЕсли;

Сообщение = Параметры.Сообщение;

НоменклатураСообщения = Новый Массив;
СворачиваниеВозможно = Не Сообщение.Товары.Колонки.Найти("СписокНоменклатуры") = Неопределено;

Для каждого СтрокаТовара Из Сообщение.Товары Цикл

	Если ЗначениеЗаполнено(СтрокаТовара.Номенклатура) Тогда
		НоменклатураСообщения.Добавить(СтрокаТовара.Номенклатура);
		Продолжить;
	КонецЕсли;

	Если СворачиваниеВозможно И ЗначениеЗаполнено(СтрокаТовара.СписокНоменклатуры) Тогда

		Для каждого СвернутаяНоменклатура Из СтрокаТовара.СписокНоменклатуры Цикл
			НоменклатураСообщения.Добавить(СвернутаяНоменклатура.Значение);
		КонецЦикла;

	КонецЕсли;

КонецЦикла;

Возврат НоменклатураСообщения;
